import pandas as pd

def merge_events(hall_events: pd.DataFrame) -> pd.DataFrame:
    if hall_events.empty:
        return pd.DataFrame(columns=['hall_id', 'start_day', 'end_day'])
    hall_events = hall_events.sort_values(['hall_id', 'start_day', 'end_day'], ascending=[True, True, False])
    results = []
    for hall_id, group in hall_events.groupby('hall_id', sort=False):
        curr_start = None
        curr_end = None
        for _, row in group.iterrows():
            s = row['start_day']
            e = row['end_day']
            if curr_start is None:
                curr_start = s
                curr_end = e
            elif s <= curr_end:
                if e > curr_end:
                    curr_end = e
            else:
                results.append({'hall_id': hall_id, 'start_day': curr_start, 'end_day': curr_end})
                curr_start = s
                curr_end = e
        if curr_start is not None:
            results.append({'hall_id': hall_id, 'start_day': curr_start, 'end_day': curr_end})
    return pd.DataFrame(results)
